function bone(x, th) {

	// line(0,0, x, y);

	beginShape();
	vertex(th / 2, 0);
	vertex(th / 4, th / 2);

	bezierVertex(th / 4, th / 2, th / 4, th, th / 4 + th / 2, th);
	bezierVertex(th / 4 + th / 2 + th / 2, th, th / 4 + th, th / 2, th / 4 + th, th / 2);

	vertex(x - th - th / 4, th / 2);
	bezierVertex(x - th - th / 4, th / 2, x - th / 2 - th / 2 - th / 4, th, x - th / 2 - th / 4, th); //
	bezierVertex(x - th / 2 + th / 2 - th / 4, th, x - th / 4, th / 2, x - th / 4, th / 2);
	vertex(x - th / 2, 0);


	vertex(x - th / 4, -th / 2);
	bezierVertex(x - th / 4, -th / 2, x - th / 2 - th / 4 + th / 2, -th, x - th / 2 - th / 4, -th); //
	bezierVertex(x - th - th / 4, -th, x - th - th / 4, -th / 2, x - th - th / 4, -th / 2);

	vertex(th + th / 4, -th / 2);
	bezierVertex(th + th / 4, -th / 2, th / 2 + th / 4 + th / 2, -th, th / 2 + th / 4, -th); //

	bezierVertex(th / 2 + th / 4 - th / 2, -th, th / 4, -th / 2, th / 4, -th / 2);


	vertex(th / 2, 0);


	endShape();
}


function skull_shape(pos, r, fi, br_zuba) {

	push();
	translate(pos.x + 0.6 * r, 0);

	beginShape();

	vertex(-0.58 * r, 0.54 * r);
	bezierVertex(-0.58 * r, 0.54 * r, -0.52 * r, 0.56 * r, -0.41 * r, 0.56 * r);
	bezierVertex(-0.3 * r, 0.56 * r, -0.34 * r, 0.75 * r, -0.23 * r, 0.75 * r);
	bezierVertex(-0.12 * r, 0.75 * r, -0.086 * r, 0.72 * r, 0.06 * r, 0.72 * r);
	bezierVertex(0.21 * r, 0.72 * r, 0.34 * r, 0.77 * r, 0.5 * r, 0.77 * r);
	bezierVertex(0.83 * r, 0.77 * r, 1.1 * r, 0.45 * r, 1.1 * r, 0 * r);

	bezierVertex(1.1 * r, -0.45 * r, 0.83 * r, -0.77 * r, 0.5 * r, -0.77 * r);
	bezierVertex(0.34 * r, -0.77 * r, 0.21 * r, -0.72 * r, 0.06 * r, -0.72 * r);
	bezierVertex(-0.086 * r, -0.72 * r, -0.12 * r, -0.75 * r, -0.23 * r, -0.75 * r);
	bezierVertex(-0.34 * r, -0.75 * r, -0.3 * r, -0.56 * r, -0.41 * r, -0.56 * r);
	bezierVertex(-0.52 * r, -0.56 * r, -0.58 * r, -0.54 * r, -0.58 * r, -0.54 * r);

	for (let k = 1; k < br_zuba - 1; k++) {
		vertex(-0.58 * r + sin(frameCount / 10 + fi[k]) * 0.15 * r, -0.54 * r + k * (0.54 * r + 0.54 * r) / (br_zuba - 1));
	}
	vertex(-0.58 * r, 0.54 * r);


	endShape();
	pop();



	push();
	translate(pos.x + 0.3 * r, 0);

	beginShape();

	vertex(-0.58 * r, -0.54 * r);

	for (let k = 1; k < br_zuba - 1; k++) {
		vertex(-0.58 * r + sin(frameCount / 10 + fi[k]) * 0.15 * r, -0.54 * r + k * (0.54 * r + 0.54 * r) / (br_zuba - 1));
