function draw() {
	randomSeed(hash_seed);
	background(bg);
	strokeWeight(1);
	let y = 0.2*height;
	for (let i=0; i<3; i++ ){
	  let iso = 0.2;
		let x = 0.5*width + ((i%2)*2-1)*random(0.1*width, 0.3*width);

		 y += (x<0.5*width)?0.3*height:0.1*height ;
		if (x<0.5*width){
			  nline( random(0,999), x, y,  cos(-iso)*width+x, sin(-iso)*width+y, 20);
		} else {	
		   nline(random(0,999), x, y , cos(PI-iso)*width+x, sin(PI-iso)*width+y , 20);
		}
	}

   // // noLoop() removed for animation
}


function nline(seed, x,y, endx, endy, n) {
