	noFill();
	stroke(0); strokeWeight(1.5);
	for (let j=0; j<30; j++){
		 pom += random(2, 8);
		 t=seed;
		beginShape();
			for (let i=n; i>=0; i--){

				let rnd = map(noise(t),0,1, 2 , 5 );
				t+=1;
				vertex( lerp(x,endx, i/n), lerp(y+pom, endy+pom, i/n)-i*rnd );
		  }
	  endShape();
		}


	for (let i=0; i<10; i++) {
		fill(boje[floor(random(0,8))]);
