	beginShape();
	 if (x>0.5*width){
		 vertex(0, endy);
		 vertex(0, height);
	   vertex(width, height);
	 }else {

	   vertex(width, height);
		 vertex(0, height);
	   vertex(0, y);
	 }

	    for (let i=0; i<=n; i++){

				var rnd = map(noise(t),0,1, 2 , 5 );
				t+=1;
				vertex( lerp(x,endx, i/n), lerp(y, endy, i/n)+i*rnd );
